export const GEAR_TIERS=Object.freeze([{min:1,max:20},{min:21,max:35},{min:36,max:50},{min:51,max:70},{min:71,max:90},{min:91,max:110},{min:111,max:130},{min:131,max:150}].map((range,i)=>Object.freeze({...range,tier:i+1,code:['I','II','III','IV','V','VI','VII','VIII'][i],name:['晨曦','征途','星輝','天啟','聖域','創世','蒼穹','永恆'][i],power:2**i})));
export const gearTierForLevel=level=>{const value=Math.min(150,Math.max(1,Math.floor(Number(level)||1)));return GEAR_TIERS.find(t=>value<=t.max).tier;};
export const gearTierRange=tier=>GEAR_TIERS[Math.min(8,Math.max(1,Math.floor(Number(tier)||1)))-1];
export const legacyFiveTierToNew=tier=>gearTierForLevel([20,40,60,80,99][Math.min(5,Math.max(1,Math.floor(Number(tier)||1)))-1]);
export function migrateFiveTierShards(bag){const result=[];for(const entry of bag){const match=!entry.uid&&/^shard_(weapon|armor)_([1-5])$/.exec(entry.id);const item=match?{...entry,id:`shard_${match[1]}_${legacyFiveTierToNew(Number(match[2]))}`}:{...entry};if(!item.uid&&/^shard_/.test(item.id)){const found=result.find(x=>x.id===item.id&&!x.uid);if(found){found.qty+=item.qty;continue;}}result.push(item);}return result;}
export const isNoviceLevel=level=>Number(level)>=1&&Number(level)<=50;
export function noviceMonsterStats(level,boss=false){const factor=boss?1.12:1;return {hp:Math.round((32+level*11+level*level*.12)*factor),atk:Math.round((4+level*1.05)*(boss?1.05:1)),def:Math.round(1+level*.34),xp:Math.max(12,Math.round((12+level*7+level*level*.13)*.9))};}

// New-continent HP and incoming pressure grow with the equipment curve.
export function normalMonsterStats(level,boss=false){const n=Math.max(0,level-51),tier=gearTierForLevel(level),power=GEAR_TIERS[tier-1].power,factor=boss?1.18:1;return {hp:Math.round((2400+n*82+n*n*1.05)*(1+power*.045)*(level>=101?2.5:1)*(level>=111?1.8:1)*factor),atk:Math.round((125+n*5.2+power*12)*(level>=101?2.5:1)*(level>=131?1.3:level>=111?1.6:1)*(boss?1.08:1)),def:Math.round((20+level*.4+power*.35)*(boss?1.1:1)),xp:Math.round((1150+n*62+n*n*.75)*(boss?1.3:1))};}
